package edu.alliance.medislot.util; import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.security.*;import java.util.*;public final class PasswordUtil{private PasswordUtil(){}private static byte[] kdf(char[] p,byte[] s)throws Exception{PBEKeySpec x=new PBEKeySpec(p,s,120000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(x).getEncoded();}finally{x.clearPassword();}}public static String hash(String p){try{byte[] s=new byte[16];new SecureRandom().nextBytes(s);return Base64.getEncoder().encodeToString(s)+":"+Base64.getEncoder().encodeToString(kdf(p.toCharArray(),s));}catch(Exception e){throw new IllegalStateException(e);}}public static boolean verify(String p,String h){try{String[] v=h.split(":");return MessageDigest.isEqual(Base64.getDecoder().decode(v[1]),kdf(p.toCharArray(),Base64.getDecoder().decode(v[0])));}catch(Exception e){return false;}}}